/**
 * Pure WGSL implementation of Hilbert R1 Blue Noise.
 * Use this version when you need to call blue noise from within wgslFn() compute shaders.
 *
 * For TSL shaders, use the regular `blueNoise` export from HibertR1BlueNoise.js instead.
 *
 * @example
 * import { blueNoiseWGSL } from '@three-blocks/core';
 *
 * const computeShader = wgslFn(`
 *   fn myCompute(...) -> void {
 *     let noise = hilbert_r1_blue_noisef(vec2i(10, 20), 8);
 *   }
 * `, [blueNoiseWGSL]);
 */
export const blueNoiseWGSL: any;
